// CreateMenu queues a create and returns the name the record will have.
func (b *graphQLBatch) CreateMenu(parent string, in *catalogpbv1.Menu) (string, error) {
	r := &GraphQLMenuRepository{Svc: b.svc}
	ci, named, err := r.newInput(parent, in)
	if err != nil {
		return "", err
	}
	if b.keys == nil {
		b.keys = map[string]string{}
	}
	b.keys[named.GetName()] = ci.Id
	queueMenuReferences(b.u, named, nil)
	b.u.QueueGraphQL(func(ctx context.Context, ops *repox.Ops) (repox.Check, error) {
		ops.Add(b.svc.Mutation.Catalog.Menus.CreateOp(ci, new(menusql.InsertCatalogMenusResponse)))
		return nil, nil
	})
	b.u.Record(repox.Change{Type: "aperio.catalog.v1/Menu", Name: named.GetName(), Op: repox.ChangeCreate, Record: named})
	return named.GetName(), nil
}

